WITH valid AS (SELECT id, order_id, carrier, delivered_date, status, LAST_DAY(shipped_date) shipped_date_month_end, FLOOR(cost) cost_whole, COALESCE(carrier, 'UNKNOWN') carrier_filled FROM shipments WHERE MONTH(delivered_date) IN (3, 6, 11) AND shipped_date >= DATE '2023-08-24'), with_dims AS (SELECT a.*, d.discount, d.channel, d.order_date FROM valid a INNER JOIN orders d ON a.order_id <=> d.id), with_windows AS (SELECT id, order_id, delivered_date, cost_whole, carrier_filled, discount, channel, order_date, LAG(discount, 1) OVER (PARTITION BY status ORDER BY cost_whole, id) prev_discount, LAG(discount, 2, 0) OVER w_hist prev_discount_2, NTILE(3) OVER (PARTITION BY carrier ORDER BY cost_whole DESC, id) cost_whole_bucket, AVG(discount) OVER (PARTITION BY channel, status ORDER BY discount, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) discount_avg_3_prior, ROW_NUMBER() OVER (PARTITION BY carrier, order_id ORDER BY shipped_date_month_end DESC, id) seq_no FROM with_dims WINDOW w_hist AS (PARTITION BY order_id ORDER BY shipped_date_month_end, id)), metrics AS (SELECT id, order_id, discount, prev_discount, prev_discount_2, discount_avg_3_prior, FIRST_VALUE(prev_discount_2, TRUE) OVER (PARTITION BY MONTH(delivered_date), channel ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_prev_discount_2, PERCENT_RANK() OVER (PARTITION BY order_id ORDER BY cost_whole_bucket) cost_whole_bucket_percent_rank FROM with_windows), joined AS (SELECT src.id, src.order_id, p.amount, p.order_date, p.status FROM metrics src LEFT JOIN orders p ON src.order_id = p.id WHERE p.customer_id = 32) SELECT id, amount FROM joined ORDER BY id DESC
